def transform(grid):
    h = len(grid)
    w = len(grid[0])
    sep = next(c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1)
    out = [row[:] for row in grid]
    border = [grid[r][w - 1] for r in range(h)]
    base = max(set(border), key=border.count)
    header_colors = {grid[0][c] for c in range(sep + 1, w - 1) if grid[0][c] != base}

    for r in range(h):
        for c in range(sep):
            if grid[r][c] in header_colors:
                out[r][c] = 0

    objects = []
    for color in header_colors:
        cells = [(i, j) for i in range(h) for j in range(sep) if grid[i][j] == color]
        if cells:
            objects.append((min(i for i, j in cells), color, cells))
    objects.sort()

    for _, color, cells in objects:
        cr = (min(i for i, j in cells) + max(i for i, j in cells)) // 2
        cc = (min(j for i, j in cells) + max(j for i, j in cells)) // 2
        for r in range(1, h - 1):
            if grid[r][w - 1] != color:
                continue
            for c in range(sep + 1, w - 1):
                if grid[0][c] == color:
                    for i, j in cells:
                        rr = r + i - cr
                        cc2 = c + j - cc
                        if 0 <= rr < h and 0 <= cc2 < w and out[rr][cc2] == 0:
                            out[rr][cc2] = color
    return out
